fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8> {
    let n = numbers.len();
    if n <= 1 {
        return numbers;
    }

    // For n >= 2, result length is 2*n - 1.
    let mut result = Vec::with_capacity(2 * n - 1);

    for (i, &x) in numbers.iter().enumerate() {
        result.push(x);
        if i + 1 != n {
            result.push(delimiter);
        }
    }

    result
}